--
-- Table structure for table `product_returns`
--

DROP TABLE IF EXISTS `product_returns`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_returns` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `return_form_id` bigint unsigned NOT NULL COMMENT 'ID phiếu trả hàng',
  `product_id` bigint unsigned NOT NULL COMMENT 'ID hàng hóa',
  `quantity` int NOT NULL COMMENT 'Số lượng',
  `serial_number_id` bigint unsigned DEFAULT NULL COMMENT 'ID số serial',
  `replacement_code` bigint unsigned DEFAULT NULL COMMENT 'ID SP đổi',
  `replacement_serial_number_id` bigint unsigned DEFAULT NULL COMMENT 'ID số serial hàng đổi',
  `extra_warranty` int DEFAULT NULL COMMENT 'Bảo hành thêm (tháng)',
  `notes` text COLLATE utf8mb4_unicode_ci COMMENT 'Ghi chú',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=482 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

