CREATE TABLE `quotations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `reception_id` bigint unsigned NOT NULL COMMENT 'ID phiếu tiếp nhận',
  `quotation_code` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Mã phiếu',
  `customer_id` bigint unsigned NOT NULL COMMENT 'ID khách hàng',
  `address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Địa chỉ khách hàng',
  `quotation_date` date NOT NULL COMMENT 'Ngày lập phiếu',
  `contact_person` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Người liên hệ',
  `notes` text COLLATE utf8mb4_unicode_ci COMMENT 'Ghi chú',
  `user_id` bigint unsigned NOT NULL COMMENT 'Người lập phiếu',
  `contact_phone` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Số điện thoại liên hệ',
  `total_amount` decimal(20,2) NOT NULL COMMENT 'Tổng tiền',
