--
-- Table structure for table `receiving`
--

DROP TABLE IF EXISTS `receiving`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `receiving` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `branch_id` bigint unsigned NOT NULL COMMENT 'Hãng tiếp nhận',
  `form_type` int unsigned NOT NULL COMMENT 'Loại phiếu',
  `form_code_receiving` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Mã phiếu',
  `customer_id` bigint unsigned NOT NULL COMMENT 'Khách hàng',
  `address` text COLLATE utf8mb4_unicode_ci COMMENT 'Địa chỉ',
  `date_created` datetime NOT NULL COMMENT 'Ngày lập phiếu',
  `contact_person` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Người liên hệ',
  `notes` text COLLATE utf8mb4_unicode_ci COMMENT 'Ghi chú',
  `user_id` bigint unsigned NOT NULL COMMENT 'Người lập phiếu',
  `phone` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Số điện thoại',
  `closed_at` datetime DEFAULT NULL COMMENT 'Ngày đóng phiếu',
  `status` int unsigned NOT NULL DEFAULT '1' COMMENT 'Tình trạng, 1:Tiếp nhận,2:Xử lí,3:Hoàn thành,4:Khách không đồng ý',
  `state` int unsigned NOT NULL DEFAULT '0' COMMENT 'Trạng thái, 0: Trống,1: Chưa xử lý vàng, 2: Quá hạn nền đỏ',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=218 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

