--
-- Table structure for table `return_form`
--

DROP TABLE IF EXISTS `return_form`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `return_form` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `reception_id` bigint unsigned NOT NULL COMMENT 'Id tiếp nhận',
  `return_code` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Mã phiếu',
  `customer_id` bigint unsigned NOT NULL COMMENT 'ID khách hàng',
  `address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Địa chỉ',
  `date_created` date NOT NULL COMMENT 'Ngày lập phiếu',
  `contact_person` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Người liên h',
  `return_method` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Phương thức trả hàng',
  `user_id` bigint unsigned NOT NULL COMMENT 'Người lập phiếu',
  `phone_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Số điện thoại',
  `notes` text COLLATE utf8mb4_unicode_ci COMMENT 'Ghi',
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '1: Hoàn thành, 2 Khách không đồng ý',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `return_form_return_code_unique` (`return_code`)
) ENGINE=InnoDB AUTO_INCREMENT=205 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

