--
-- Table structure for table `warranty_lookup`
--

DROP TABLE IF EXISTS `warranty_lookup`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `warranty_lookup` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `product_id` int NOT NULL,
  `sn_id` int NOT NULL,
  `customer_id` int DEFAULT NULL,
  `name_warranty` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `name_status` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `export_return_date` datetime DEFAULT NULL,
  `warranty` int DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_expire_date` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Thông tin bảo hành thêm',
  `warranty_expire_date` datetime DEFAULT NULL COMMENT 'Ngày hết hạn bảo hành',
  `warranty_extra` int DEFAULT NULL,
  `return_date` datetime DEFAULT NULL COMMENT 'Ngày trả hàng',
  `service_warranty_expired` datetime DEFAULT NULL COMMENT 'Ngày hết hạn bảo hành dịch vụ',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `export_id` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3183 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

